begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values
('50000000-0000-4000-8000-000000000001','community-a@example.test','{"provider":"email"}','{"username":"community_a"}'),
('50000000-0000-4000-8000-000000000002','community-b@example.test','{"provider":"email"}','{"username":"community_b"}');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and not c.relrowsecurity),'Every public table has RLS');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.start_study_session(25,'rain-desk',null,'{"mode":"characters","characterSlugs":["male-01"]}')$$,'Session starts through trusted RPC');
select is((public.start_study_session(5,'rain-desk',null,'{"mode":"solo","characterSlugs":[]}')).id,(select id from public.sessions where user_id=auth.uid() and ended_at is null),'Double start returns same session');
select throws_ok($$insert into public.sessions(user_id,planned_minutes,theme_slug) values(auth.uid(),5,'rain-desk')$$,'42501',null,'Client cannot insert timestamps or durations');
reset role;
-- Historical fixtures use trusted INSERT; immutable origins are never rewritten.
update public.sessions set ended_at=started_at,ended_reason='completed' where user_id='50000000-0000-4000-8000-000000000001';
insert into public.sessions(user_id,started_at,planned_minutes,theme_slug) values('50000000-0000-4000-8000-000000000001',now()-interval '10 hours',25,'rain-desk');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((public.finish_study_session((select id from public.sessions where user_id=auth.uid() and ended_at is null),'stopped_early')).actual_seconds,21600,'Repository caps ten hours at six hours');
select is((public.finish_study_session((select id from public.sessions where user_id=auth.uid() order by started_at limit 1),'completed')).actual_seconds,21600,'Repeat Finish is idempotent');
select is((public.study_summary()->>'totalSeconds')::integer,21600,'Time is banked once');
select is((select sum((day->>'totalSeconds')::integer) from jsonb_array_elements(public.study_days('2000-01-01','2099-01-01')) day),21600::bigint,'Day totals conserve lifetime time');
select is((select count(*) from public.achievement_awards where user_id=auth.uid()),1::bigint,'First day awards one permanent badge');
select throws_ok($$insert into public.achievement_awards(user_id,milestone) values(auth.uid(),600)$$,'42501',null,'Client cannot forge awards');
select public.community_mutate('task.create','{"title":"Private task","date":"2026-10-16"}');
select is(jsonb_array_length(public.community_read('tasks')->'items'),1,'Owner sees task');
select public.community_mutate('group.create','{"title":"Private group","body":"Notes","private":true}');
select set_config('test.group',(select id::text from public.study_groups where owner_id=auth.uid()),true);
select public.community_mutate('room.create','{"title":"One seat","body":"Quiet","category":"deep","private":false,"capacity":1}');
select set_config('test.room',(select id::text from public.study_rooms where owner_id=auth.uid()),true);
select lives_ok($$select public.community_mutate('room.join',jsonb_build_object('id',current_setting('test.room')))$$,'Room membership is explicit');
select lives_ok($$select public.community_mutate('room.join',jsonb_build_object('id',current_setting('test.room')))$$,'Join is idempotent');
select is(jsonb_array_length(public.community_read('room',jsonb_build_object('id',current_setting('test.room')))->'context'->'people'),1,'Presence comes from real visits');
select public.community_mutate('preferences','{"allowMessages":true}');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.sessions),0::bigint,'Other account cannot read sessions');
select is(jsonb_array_length(public.community_read('tasks')->'items'),0,'Other account cannot read private tasks');
select throws_ok($$select public.community_read('groups',jsonb_build_object('id',current_setting('test.group')))$$,'42501',null,'Private group is hidden');
select lives_ok($$select public.community_mutate('group.join',jsonb_build_object('id',current_setting('test.group')))$$,'Private membership can be requested');
select throws_ok($$select public.community_read('groups',jsonb_build_object('id',current_setting('test.group')))$$,'42501',null,'Pending membership cannot read group content');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.community_mutate('group.approve',jsonb_build_object('id',current_setting('test.group'),'targetId','50000000-0000-4000-8000-000000000002'))$$,'Owner can approve a request');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select lives_ok($$select public.community_read('groups',jsonb_build_object('id',current_setting('test.group')))$$,'Approved membership opens group content');
select throws_ok($$select public.moderate_room(current_setting('test.room')::uuid,'50000000-0000-4000-8000-000000000001')$$,'42501',null,'Nonmanager cannot remove a room member');
select throws_ok($$select public.community_mutate('room.join',jsonb_build_object('id',current_setting('test.room')))$$,'P0001','Room is full','Capacity is enforced by server');
select throws_ok($$select public.community_mutate('room.share',jsonb_build_object('id',current_setting('test.room'),'value',true))$$,'42501',null,'Nonmember cannot publish');
select public.community_mutate('thread.direct','{"targetId":"50000000-0000-4000-8000-000000000001"}');
select set_config('test.thread',(select id::text from public.conversation_threads where kind='direct' limit 1),true);
select public.community_mutate('message.send',jsonb_build_object('id',current_setting('test.thread'),'body','Hello','clientId','60000000-0000-4000-8000-000000000001'));
select public.community_mutate('message.send',jsonb_build_object('id',current_setting('test.thread'),'body','Hello','clientId','60000000-0000-4000-8000-000000000001'));
select is(jsonb_array_length(public.community_read('messages',jsonb_build_object('id',current_setting('test.thread')))->'items'),1,'Retried delivery cannot duplicate a message');
select public.community_mutate('block.set','{"targetId":"50000000-0000-4000-8000-000000000001","value":true}');
select throws_ok($$select public.community_mutate('thread.direct','{"targetId":"50000000-0000-4000-8000-000000000001"}')$$,'42501',null,'Block prevents direct messaging');
select throws_ok($$select public.community_mutate('message.send',jsonb_build_object('id',current_setting('test.thread'),'body','Blocked','clientId','60000000-0000-4000-8000-000000000002'))$$,'42501',null,'Block stops existing-thread messages');
select public.community_mutate('post.create','{"body":"A real update"}');
select is(jsonb_array_length(public.community_read('feed','{"filter":"following"}')->'items'),1,'Following feed includes the posted update');
select throws_ok($$select public.community_mutate('post.create','{"body":"Attachment","attachments":[{"path":"50000000-0000-4000-8000-000000000001/60000000-0000-4000-8000-000000000001.png","mime":"image/png","name":"x","size":1}]}')$$,'23514',null,'Cannot attach another account media');
select is(jsonb_array_length(public.community_leaderboard('time','all')->'items'),0,'Leaderboard is opt-in');
select public.community_mutate('preferences','{"leaderboardOptIn":true}');
select is(jsonb_array_length(public.community_leaderboard('time','all')->'items'),1,'Opted-in account enters a newly populated snapshot');
select ok(public.community_read('plans')->'context' ? 'usedSeconds','Plan reports trusted interval usage');
select throws_ok($$update public.plan_policies set daily_room_seconds=999999$$,'42501',null,'Client cannot grant own allowance');
select public.community_mutate('event.create',jsonb_build_object('title','Booked focus','startsAt',now()+interval '2 days','minutes',30,'capacity',1));
select set_config('test.event',(select id::text from public.scheduled_sessions where creator_id=auth.uid()),true);
select is((select count(*) from public.session_bookings where event_id=current_setting('test.event')::uuid),1::bigint,'Host booking counts against capacity');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.community_mutate('event.book',jsonb_build_object('id',current_setting('test.event')))$$,'P0001','Session is full','Booking capacity is atomic');
select * from finish();
rollback;
